import json

class JSONHandler:
    _registry = {}

    @staticmethod
    def register_factory(class_id, factory_function):
        JSONHandler._registry[class_id] = factory_function

    @staticmethod
    def from_json(json_string, class_id):
        data = json.loads(json_string)
        return JSONHandler._registry[class_id](**data)

    def to_json(self):
        return json.dumps(self.__dict__)

class SubClass(JSONHandler):
    def __init__(self, name, value):
        self.name = name
        self.value = value

def create_subclass_instance(**kwargs):
    return SubClass(**kwargs)

JSONHandler.register_factory('subclass', create_subclass_instance)

# Example usage:
instance = SubClass('example', 42)
json_string = instance.to_json()
new_instance = JSONHandler.from_json(json_string, 'subclass')
print(new_instance.name)  # Output: example
