0,"Create a Python program that develops a custom data compression algorithm for text files. The program should include a module, class with methods for compression and decompression, and utilize the standard library's 'io' module to handle the text file. The compression algorithm should be implemented as a static method within the class, using an efficient approach such as Huffman coding or Run-Length Encoding. The program should also include user input functionality to allow the user to specify the file path and choose between compressing or decompressing the text file. Additionally, provide output functionality to display both the original and compressed/decompressed text for verification.",335,,"['```python
import io
from collections import Counter

class TextCompressor:
    @staticmethod
    def huffman_encode(data):
        freq = Counter(data)
        heap = [[weight, [symbol, """"]] for symbol, weight in freq.items()]
        while len(heap) > 1:
            lo = heapq.heappop(heap)
            hi = heapq.heappop(heap)
            for pair in lo[1:]:
                pair[1] = '0' + pair[1]
            for pair in hi[1:]:
                pair[1] = '1' + pair[1]
            heapq.heappush(heap, [lo[0] + hi[0]] + lo[1:] + hi[1:])
        return sorted(heapq.heappop(heap)[1:], key=lambda p: (len(p[-1]), p))

    @staticmethod
    def huffman_decode(encoded_data, huff_table):
        decode_map = {code: symbol for symbol, code in huff_table}
        decoded_text = """"
        current_code = """"
        for bit in encoded_data:
            current_code += bit
            if current_code in decode_map:
                decoded_text += decode_map[current_code]
                current_code = """"
        return decoded_text

    @staticmethod
    def compress(text):
        huff_table = TextCompressor.huffman_encode(text)
        encoded_data = """".join([code for symbol, code in huff_table])
        compressed_data = io.BytesIO()
        compressed_data.write(len(huff_table).to_bytes(2, byteorder='big'))
        compressed_data.write(io.StringIO(encoded_data).getvalue().encode('utf-8'))
        return compressed_data.getvalue()

    @staticmethod
    def decompress(compressed_data):
        huff_table_len = int.from_bytes(compressed_data[:2], byteorder='big')
        encoded_data = io.BytesIO(compressed_data[2:])
        encoded_text = encoded_data.read().decode('utf-8')
        huff_table = []
        for _ in range(huff_table_len):
            symbol = encoded_text[0]
            encoded_text = encoded_text[1:]
            while encoded_text and encoded_text[0] == '0':
                encoded_text = encoded_text[1:]
                symbol += '0'
            huff_table.append([symbol, encoded_text[:len(symbol)]])
            encoded_text = encoded_text[len(symbol):]
        return TextCompressor.huffman_decode(encoded_data.getvalue(), huff_table)

if __name__ == ""__main__"":
    file_path = input(""Enter the file path: "")
    with open(file_path, 'r') as file:
        text = file.read()

    print(""Original Text:"", text)
    choice = input(""Choose operation (1 to compress, 2 to decompress): "")

    if choice == '1':
        compressed_text = TextCompressor.compress(text)
        print(""Compressed Text:"", compressed_text)
    elif choice == '2':
        decompressed_text = TextCompressor.decompress(compressed_text)
        print(""Decompressed Text:"", decompressed_text)
    else:
        print(""Invalid choice."")
```']",0,[0],[],True,0,0,0,

