import random

def updateGraphStream(graph, numVertices, numEdges):
    streamData = []

    def addElementsToGraph(numVertices, numEdges):
        vertexProps = generateRandomProperties()
        edgeProps = generateRandomProperties()

        for i in range(numVertices):
            newVertexId = generateNewVertexId()
            graph.addNode(newVertexId, vertexProps)
            streamData.append(f""Added vertex {newVertexId} with properties: {vertexProps}"")

        for i in range(numEdges):
            sourceVertexId = generateRandomVertexId(graph)
            targetVertexId = generateRandomVertexId(graph)
            graph.addEdge(sourceVertexId, targetVertexId, edgeProps)
            streamData.append(f""Added edge between {sourceVertexId} and {targetVertexId} with properties: {edgeProps}"")

    def pause():
        print(""Update process paused"")

    def resume():
        print(""Update process resumed"")

    def generateRandomProperties():
        return {""property1"": random.random(), ""property2"": random.random()}

    def generateNewVertexId():
        return f'vertex_{random.random().str(36).substr(2, 9)}'

    def generateRandomVertexId(graph):
        existingIds = list(graph.nodes())
        return existingIds[random.randint(0, len(existingIds) - 1)]

    addElementsToGraph(numVertices, numEdges)
