import json

class JSONParserCreator:
    def __init__(self):
        self.registry = {}

    def add_factory(self, factory_id, factory_function):
        self.registry[factory_id] = factory_function

    def create_instance(self, id_str, data):
        factory_id = int(id_str)
        if factory_id in self.registry:
            return self.registry[factory_id](data)
        else:
            raise ValueError(""Factory function for ID {} not found"".format(factory_id))

    def to_json_string(self, data):
        return json.dumps(data)

    def from_json_string(self, json_str):
        return json.loads(json_str)

# Example usage

class DataModel:
    def __init__(self, data):
        self.data = data

def create_data_model(data):
    return DataModel(data)

parser_creator = JSONParserCreator()
