class JSONParser:
    factory_functions = {}

    @staticmethod
    def register_factory(class_id, factory_func):
        JSONParser.factory_functions[class_id] = factory_func

    @classmethod
    def create_instance(cls, class_id, *args, **kwargs):
        if class_id in cls.factory_functions:
            return cls.factory_functions[class_id](*args, **kwargs)
        else:
            raise ValueError(f""Factory function for {class_id} not registered"")

class CustomerGenerator:
    @staticmethod
    def generate_customer_info():
        random_gen = EnhancedRandomGenerator()
