        account_number = random_gen.generate_unique_account_number()
        total_spending = random_gen.generate_random_float(1000.0, 5000.0)
        return CUSTOMERINFO_T(customer_name, account_number, total_spending)

def unique_account_number_generator():
    used_numbers = set()

    def generate():
        while True:
            number = EnhancedRandomGenerator().generate_random_int(100000, 999999)
            if number not in used_numbers:
                used_numbers.add(number)
                return number

    return generate

JSONParser.register_factory(""CUSTOMERINFO_T"", CustomerGenerator.generate_customer_info)

