void register_cryptographic_algorithms() {
    // Check if there's enough space in the library for all algorithms
    if (EVP_add_cipher(cipher_list, sizeof(cipher_list) / sizeof(cipher_list[0])) != 1 ||
        EVP_add_digest(digest_list, sizeof(digest_list) / sizeof(digest_list[0])) != 1 ||
