# C# part: EnhancedRandomGenerator Class (simulated in Python using NumPy for simplicity)
import numpy as np

class EnhancedRandomGenerator:
    def __init__(self, min_val, max_val):
        self.min_val = min_val
        self.max_val = max_val

    def generate_random_float(self):
        return np.random.uniform(self.min_val, self.max_val)

    def generate_random_int(self):
        return round(np.random.uniform(self.min_val, self.max_val))

    def __str__(self):
        return f""Range: {self.min_val}-{self.max_val}""

# Example usage
if __name__ == ""__main__"":
    random_gen = EnhancedRandomGenerator(1000, 9999)
    customer_json = JSONManager.create_customer(
        ""John Doe"",
        str(int(random_gen.generate_random_int())),
        str(round(random_gen.generate_random_float(), 2))
    )
    print(customer_json)
