        self.playing_status = False

    def play_sound_buffer(self):
        if not self.sound_buffer:
            mixer.music.play()
            self.playing_status = True

    def pause_sound(self):
        if self.playing_status:
            mixer.music.pause()
            self.playing_status = False

    def resume_sound(self):
        if not self.playing_status:
            mixer.music.unpause()
            self.playing_status = True

    def stop_sound(self):
        if mixer.music.get_busy():
            mixer.music.stop()

    def toggle_play_pause(self):
        if not mixer.music.get_busy():
            mixer.music.play()
            print(""Playing..."")

