0,"Design a Python class to manage XML objects, featuring methods for converting data into an XML string and instantiating a new object from an XML string. The class should include a registry to store factory functions, categorized by tag name, which can create instances of derived classes. Implement functions for adding new factory functions to the registry and generating a new instance of a subclass using the corresponding factory function associated with a tag name.",94,,"['```python
import xml.etree.ElementTree as ET

class XMLManager:
    _registry = {}

    @classmethod
    def register_factory(cls, tag_name, factory_func):
        cls._registry[tag_name] = factory_func

    @classmethod
    def from_xml_string(cls, xml_str):
        root = ET.fromstring(xml_str)
        tag_name = root.tag
        if tag_name in cls._registry:
            return cls._registry[tag_name](root)
        else:
            raise ValueError(f""No factory registered for tag: {tag_name}"")

class BaseXMLObject:
    def to_xml_string(self):
        root = ET.Element(""base"")
        # Add child elements based on the object's state
        return ET.tostring(root, encoding='unicode')

class DerivedXMLObject(BaseXMLObject):
    @classmethod
    def from_xml_element(cls, element):
        # Create an instance and set properties based on the XML element
        obj = cls()
        for child in element:
            setattr(obj, child.tag, child.text)
        return obj

    def to_xml_string(self):
        root = ET.Element(""derived"")
        # Add child elements based on the object's state
        return ET.tostring(root, encoding='unicode')

# Registering the factory function for DerivedXMLObject
XMLManager.register_factory(""derived"", DerivedXMLObject.from_xml_element)

# Example usage:
xml_str = ""<derived><name>Example</name></derived>""
obj = XMLManager.from_xml_string(xml_str)
print(obj.to_xml_string())
