class DataCleaner:
    def __init__(self, data, parameters):
        self._data = data
        self._parameters = parameters

    def clean_data(self):
        # Implement data cleaning logic here
        cleaned_data = self._data.drop_duplicates()
        if self._parameters.get('handle_missing'):
            cleaned_data.fillna(method='ffill', inplace=True)
        if self._parameters.get('convert_dtypes'):
            for col, dtype in self._parameters['dtype_map'].items():
                cleaned_data[col] = cleaned_data[col].astype(dtype)
        return cleaned_data

    def apply_custom_transformations(self):
