enum TokenKind<'a> {
    Code(&'a str),
    Comment(&'a str),
    BlockComment(&'a str),
}

struct ParserState<'a> {
    current_node: ParserNode<'a>,
}

impl<'a> ParserState<'a> {
    fn new(root_value: &'a str) -> Self {
        ParserState { current_node: ParserNode { value: root_value } }
    }

    fn push_token(mut self, token_kind: TokenKind<'_>) -> Self {
        match token_kind {
            TokenKind::Code(code) => self.current_node.children.push(ParserNode { value: code }),
            TokenKind::Comment(comment) => self.current_node.children.push(ParserNode { value: comment }),
            TokenKind::BlockComment(block_comment) => self.current_node.children.push(ParserNode { value: block_comment }),
        }

column8:
        ParserState { current_node: self.current_node }
    }

    fn finalize(self) -> Vec<ParserNode<'_>> {
        vec![self.current_node]
    }
}

