0,"Develop a Python function aimed at establishing a connection to a remote MQTT broker, subscribing to a designated topic, and recording received messages within a text file. Incorporate error management mechanisms for connection failures and design the function to execute in an iterative, user-controlled termination loop.",918,,"['```python
import paho.mqtt.client as mqtt

def connect_mqtt_and_log_messages(broker_address, broker_port, topic, log_file):
    client = mqtt.Client()

    def on_connect(client, userdata, flags, rc):
        if rc == 0:
            print(""Connected to MQTT Broker"")
            client.subscribe(topic)
        else:
            print(f""Failed to connect, return code {rc}"")

    def on_message(client, userdata, msg):
        with open(log_file, 'a') as file:
            file.write(f""{msg.topic} - {msg.payload.decode()}\n"")

    client.on_connect = on_connect
    client.on_message = on_message

    try:
        client.connect(broker_address, broker_port)
        client.loop_start()

        while True:
            user_input = input(""Type 'exit' to terminate: "")
            if user_input == 'exit':
                break

        client.loop_stop()
        client.disconnect()
        print(""Connection terminated."")

    except Exception as e:
        print(f""An error occurred: {e}"")

# Example usage
connect_mqtt_and_log_messages('broker.hivemq.com', 1883, 'test/topic', 'messages.log')
```']",0,[0],[],True,0,0,0,

