0,"Create a Python class named ""LibrarySystem"" that simulates a simple library management system. The class should have methods for adding books, removing books, searching for books by title or author, and displaying all available books. Implement error handling to log messages when an attempt is made to remove a book that does not exist or search for a book that is not in the library. Additionally, include a method to display statistics such as the total number of books and the most borrowed book.",78,,"['```python
class LibrarySystem:
    def __init__(self):
        self.books = {}
        self.borrowed_books = {}

    def add_book(self, title, author):
        if title in self.books:
            print(f""Book '{title}' already exists."")
        else:
            self.books[title] = {'author': author, 'borrowed': False}
            print(f""Book '{title}' added successfully."")

    def remove_book(self, title):
        if title not in self.books:
            print(f""Book '{title}' not found."")
        else:
            del self.books[title]
            print(f""Book '{title}' removed successfully."")

    def search_by_title(self, title):
        if title not in self.books:
            print(f""Book '{title}' not found."")
        else:
            book_info = self.books[title]
            print(f""Title: {book_info['title']}, Author: {book_info['author']}"")

    def search_by_author(self, author):
        found_books = [title for title, info in self.books.items() if info['author'] == author]
        if not found_books:
            print(f""No books found by author '{author}'."")
        else:
            for book in found_books:
                print(f""Title: {book}, Author: {self.books[book]['author']}"")

    def display_books(self):
        if not self.books:
            print(""No books available."")
        else:
            for title, info in self.books.items():
                status = ""Borrowed"" if info['borrowed'] else ""Available""
                print(f""Title: {title}, Author: {info['author']}, Status: {status}"")

    def borrow_book(self, title):
        if title not in self.books:
            print(f""Book '{title}' not found."")
        elif self.books[title]['borrowed']:
            print(f""Book '{title}' is already borrowed."")
        else:
            self.books[title]['borrowed'] = True
            if title not in self.borrowed_books:
                self.borrowed_books[title] = 1
            else:
                self.borrowed_books[title] += 1
            print(f""Book '{title}' borrowed successfully."")

    def return_book(self, title):
        if title not in self.books:
            print(f""Book '{title}' not found."")
        elif not self.books[title]['borrowed']:
            print(f""Book '{title}' is not currently borrowed."")
        else:
            self.books[title]['borrowed'] = False
            if title not in self.borrowed_books or self.borrowed_books[title] == 1:
                del self.borrowed_books[title]
            else:
                self.borrowed_books[title] -= 1
            print(f""Book '{title}' returned successfully."")

    def display_statistics(self):
        total_books = len(self.books)
        most_borrowed = max(self.borrowed_books.items(), key=lambda x: x[1]) if self.borrowed_books else ('None', 0)
        print(f""Total Books: {total_books}"")
        print(f""Most Borrowed Book: '{most_borrowed[0]}' with {most_borrowed[1]} borrows"")
