```",338,,"['Here is the code for the `AdvancedNumberGenerator` class with methods to generate both float and integer numbers within a specified range, including handling edge cases where the minimum or maximum values should be included or excluded:

```python
import random

class AdvancedNumberGenerator:
    def __init__(self, min_val=None, max_val=None, include_min=True, include_max=True):
        self.min_val = min_val
        self.max_val = max_val
        self.include_min = include_min
        self.include_max = include_max

    def set_range(self, min_val, max_val, include_min=True, include_max=True):
        self.min_val = min_val
        self.max_val = max_val
        self.include_min = include_min
        self.include_max = include_max

    def generate_float(self):
        start = self.min_val if self.include_min else None
        end = self.max_val if self.include_max else None + random.uniform(-1.0e-9, 1.0e-9)
        return random.uniform(start, end)

    def generate_int(self):
        start = int(self.min_val) if self.include_min else None
        end = int(self.max_val) if self.include_max else None + 1 + random.uniform(-1.0e-9, 1.0e-9)
        return int(random.uniform(start, end))

    def display_range(self):
        settings_str = ""Range Settings: ""

        if not (self.include_min or (self.min_val is not None)):
            settings_str += ""Exclude Min Value""

        if not (self.include_max or (self.max_val is not None)):
            settings_str += "" Exclude Max Value""

        return settings_str

# Example usage:
rng_float_generator = AdvancedNumberGenerator(5.0, 20.0)
rng_int_generator   = AdvancedNumberGenerator(50, 75)

print(rng_float_generator.generate_float())
print(rng_int_generator.generate_int())
print(rng_float_generator.display_range())
print(rng_int_generator.display_range())
```

