329,"Design and implement a Python class named `MD5HashGenerator` that includes methods to generate an MD5 hash for a given input string, test the hash generation function with a specific string, and calculate the difference between two generated MD5 hashes. The class should also have an optional parameter to specify the number of iterations for hash generation. Additionally, create a subclass named `EnhancedMD5HashGenerator` that inherits from `MD5HashGenerator` and introduces a method to calculate the bitwise XOR between two hashes. Provide an example usage of both classes in their main methods.",327,,"['```python
import hashlib

class MD5HashGenerator:
    def __init__(self, iterations=1):
        self.iterations = iterations

    def generate_hash(self, input_string):
        hash_object = hashlib.md5(input_string.encode())
        for _ in range(1, self.iterations):
            hash_object.update(hash_object.hexdigest().encode())
        return hash_object.hexdigest()

    @staticmethod
    def test_generate_hash():
        generator = MD5HashGenerator(iterations=2)
        input_string = ""test""
        expected_hash = ""6f8db599de986fab7a21625b7916589c""
        assert generator.generate_hash(input_string) == expected_hash, ""Test failed""

    @staticmethod
    def calculate_hash_difference(hash1, hash2):
        return bin(int(hash1, 16) ^ int(hash2, 16))[2:].zfill(32)

class EnhancedMD5HashGenerator(MD5HashGenerator):
    def xor_hashes(self, hash1, hash2):
        return self.calculate_hash_difference(hash1, hash2)

def main():
    md5_generator = MD5HashGenerator(iterations=2)
    enhanced_md5_generator = EnhancedMD5HashGenerator(iterations=3)

    input_string = ""example""
    hash_value = md5_generator.generate_hash(input_string)
    print(f""MD5 Hash: {hash_value}"")

    md5_generator.test_generate_hash()

    hash1 = md5_generator.generate_hash(""first"")
    hash2 = md5_generator.generate_hash(""second"")
    xor_result = enhanced_md5_generator.xor_hashes(hash1, hash2)
    print(f""XOR Result: {xor_result}"")

if __name__ == ""__main__"":
    main()
