from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.hazmat.primitives.asymmetric import padding
from cryptography.hazmat.primitives import hashes
import secrets

def generate_rsa_keys():
    private_key = rsa.generate_private_key(
        public_exponent=65537,
        key_size=2048,
    )
    public_key = private_key.public_key()
    return private_key, public_key

def encrypt_message(message, public_key):
    try:
        encrypted_message = public_key.encrypt(
            message.encode(),
            padding.OAEP(
                mgf=padding.MGF1(algorithm=hashes.SHA256()),
                algorithm=hashes.SHA256(),
                label=None
            )
        )
        return encrypted_message
    except Exception as e:
        print(f""Error encrypting message: {e}"")
        return None

def generate_random_string(length):
    return ''.join(secrets.choice('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') for _ in range(length))

def main():
    private_key, public_key = generate_rsa_keys()

    input_message = input(""Enter a message to encrypt: "")
    encrypted_message = encrypt_message(input_message, public_key)
    if encrypted_message:
        print(f""Encrypted Message: {encrypted_message}"")

        random_string_length = int(input(""Enter the length of the random string: ""))
        random_string = generate_random_string(random_string_length)
        print(f""Random String: {random_string}"")

if __name__ == ""__main__"":
