import os
import sys
import hashlib

def calculate_checksum(file_path, output_format='hex'):
    try:
        with open(file_path, 'rb') as file:
            file_content = file.read()
            checksum = hashlib.md5(file_content).hexdigest()
    except FileNotFoundError:
        print(""Error: File not found."")
        return None

    if output_format == 'hex':
        return checksum
    elif output_format == 'bin':
        return bytes.fromhex(checksum).decode()
    else:
        print(""Error: Invalid output format."")
        return None

def main():
    if len(sys.argv) < 2:
        print(""Usage: python script.py [options]"")
        print(""--help to display usage information"")
        print(""-f file_path to specify the input file"")
        print(""-s to output the result as a hexadecimal string"")
        return

    options = sys.argv[1:]

    if '--help' in options:
        print(""Usage: python script.py [options]"")
        print(""--help to display usage information"")
        print(""-f file_path to specify the input file"")
        print(""-s to output the result as a hexadecimal string"")

    elif '-f' in options and '-s' in options:
        index_file = options.index('-f')

        try:
            index_s = options.index('-s')
            output_format = 'hex'

            if index_s < index_file + 2 or index_s > len(options) - 1:
                raise ValueError

            input_file = options[index_file + 1]

            checksum_result = calculate_checksum(input_file, output_format)

            if checksum_result is not None:
                print(f""Checksum (Hex): {checksum_result}"")

            else:
                sys.exit(1)


except Exception as e:
    print(f""An error occurred: {str(e)}"")

if __name__ == ""__main__"":
    main()
