import random

class USER_DATA:
    def __init__(self, data):
        self.data = data

class USER_RECORD:
    def __init__(self, user_data, sequence_number):
        self.user_data = user_data
        self.sequence_number = sequence_number

def generate_user_records(num_records):
    records = []
    used_numbers = set()

    for _ in range(num_records):
        while True:
            sequence_number = random.randint(1, 100000)  # Adjust the range as needed
            if sequence_number not in used_numbers:
                used_numbers.add(sequence_number)
                break

        user_data = USER_DATA(bytearray(random.getrandbits(8) for _ in range(16)))  # 16-byte random byte string
        records.append(USER_RECORD(user_data, sequence_number))

    return records

# Example usage
user_records = generate_user_records(5)
