0,"Create a Python script that accepts command line arguments to perform actions on a text file. Options include --help for usage instructions, -s search_string to count occurrences, and -c to count lines. The script should handle these options correctly, report invalid inputs or missing file paths, and print results for each action.",121,,"['```python
import argparse

def count_lines(filename):
    with open(filename, 'r') as file:
        return len(file.readlines())

def search_string(filename, search_term):
    with open(filename, 'r') as file:
        content = file.read()
        return content.count(search_term)

def main():
    parser = argparse.ArgumentParser(description='Text file operations')
    parser.add_argument('-f', '--file', required=True, help='Path to the text file')
    parser.add_argument('-s', '--search_string', help='String to search for and count occurrences')
    parser.add_argument('-c', action='store_true', help='Count the number of lines in the file')

    args = parser.parse_args()

    if not args.file:
        print(""Error: File path is required"")
        return

    try:
        if args.search_string:
            print(f""Occurrences of '{args.search_string}': {search_string(args.file, args.search_string)}"")
        if args.c:
            print(f""Number of lines: {count_lines(args.file)}"")
    except FileNotFoundError:
        print(""Error: File not found"")
    except Exception as e:
        print(f""An error occurred: {e}"")

if __name__ == ""__main__"":
    main()
