0,"Design a Python software harnessing the concurrent.futures library to concurrently download several sizable files from the internet. Establish an `IFileDownloader` abstract class for handling download operations. Architect a `FileDownloaderManager` entity to orchestrate the downloading process, spawn threads or processes for each file, track their statuses, address exceptions, and interpret response codes post completion or failure. Determine the ideal number of concurrent download processes based on accessible CPU cores, employ ThreadPoolExecutor or ProcessPoolExecutor to execute tasks in parallel, oversee response codes, and ensure proper resource cleanup once all files are downloaded or an error surfaces.",590,,"['```python
from abc import ABC, abstractmethod
import concurrent.futures
import requests

class IFileDownloader(ABC):
    @abstractmethod
    def download_file(self, url: str) -> None:
        pass

class FileDownloader(IFileDownloader):
    def download_file(self, url: str) -> None:
        response = requests.get(url)
        if response.status_code == 200:
            with open(url.split('/')[-1], 'wb') as file:
                file.write(response.content)
        else:
            raise Exception(f""Failed to download {url} with status code {response.status_code}"")

class FileDownloaderManager:
    def __init__(self, num_processes=None):
        self.num_processes = num_processes or concurrent.futures.ProcessPoolExecutor._processes
        self.executor = concurrent.futures.ThreadPoolExecutor(max_workers=self.num_processes)

    def download_files(self, urls: list) -> None:
        future_to_url = {self.executor.submit(file_downloader.download_file, url): url for file_downloader in [FileDownloader() for _ in range(len(urls))] for url in urls}
        for future in concurrent.futures.as_completed(future_to_url):
            url = future_to_url[future]
