0,"Create a Python program that uses dynamic memory allocation to manage a list of book inventory records. The program should allow for adding, updating, removing book records, and calculating the average price of all books. Implement a Book class with attributes for ID, title, author, and price. Include methods for adding new records, updating existing ones, removing records from the list, and calculating the average price of all books in the inventory. Employ a hash function to securely store and manage sensitive data related to each book record.",328,,"['```python
import hashlib

class Book:
    def __init__(self, id, title, author, price):
        self.id = id
        self.title = title
        self.author = author
        self.price = price

    def update_price(self, new_price):
        self.price = new_price

    def to_dict(self):
        return {
            'id': self.id,
            'title': self.title,
            'author': self.author,
            'price': self.price
        }

class BookInventory:
    def __init__(self):
        self.inventory = {}

    def add_book(self, book):
        self.inventory[book.id] = book

    def update_book(self, id, new_price):
        if id in self.inventory:
            self.inventory[id].update_price(new_price)

    def remove_book(self, id):
        if id in self.inventory:
            del self.inventory[id]

    def average_price(self):
        total_price = sum(book.price for book in self.inventory.values())
        return total_price / len(self.inventory) if self.inventory else 0

    def to_dict(self):
        return {book.id: book.to_dict() for book in self.inventory.values()}

# Example usage:
inventory = BookInventory()
book1 = Book(1, ""1984"", ""George Orwell"", 15.99)
book2 = Book(2, ""To Kill a Mockingbird"", ""Harper Lee"", 10.99)

inventory.add_book(book1)
inventory.add_book(book2)

print(""Initial Inventory:"")
for book_id, details in inventory.to_dict().items():
    print(f""ID: {details['id']}, Title: {details['title']}, Author: {details['author']}, Price: ${details['price']}"")

inventory.update_book(1, 14.99)
inventory.remove_book(2)

print(""\nUpdated Inventory:"")
for book_id, details in inventory.to_dict().items():
    print(f""ID: {details['id']}, Title: {details['title']}, Author: {details['author']}, Price: ${details['price']}"")

average = inventory.average_price()
print(f""\nAverage Book Price: ${average:.2f}"")
```']",0,[0],[],True,0,0,0,

