import random

class LocationIdentifier:
    def __init__(self, identifier, latitude, longitude):
        self.identifier = identifier
        self.latitude = latitude
        self.longitude = longitude

def generate_lid_structures(num_locations, min_identifier=100, max_identifier=999, min_latitude=-90.0, max_latitude=90.0, min_longitude=-180.0, max_longitude=180.0):
    lid_structures = []
    for i in range(num_locations):
        while True:
            identifier = random.randint(min_identifier, max_identifier)
            latitude = round(random.uniform(min_latitude, max_latitude), 2)
            longitude = round(random.uniform(min_longitude, max_longitude), 2)

            if min_latitude <= latitude <= max_latitude and min_longitude <= longitude <= max_longitude:
                lid_structures.append(LocationIdentifier(identifier, latitude, longitude))
                break
            else:
                print(f""Invalid coordinates for LID {identifier}: Latitude and Longitude must be within the specified ranges."")
    return lid_structures

# Example usage:
lids = generate_lid_structures(5)
for lid in lids:
    print(f""LID: {lid.identifier}, Latitude: {lid.latitude}, Longitude: {lid.longitude}"")
