4. A new `wait_for_completion` method has been added to the `FileDownloaderManager` class to monitor all downloads",590,,"['```python
import concurrent.futures
import requests
from abc import ABC, abstractmethod
from typing import List

class IFileDownloader(ABC):
    @abstractmethod
    def download_file(self, url: str, filename: str) -> bool:
        pass

class FileDownloaderManager:
    def __init__(self, num_processes: int = None):
        self.num_processes = num_processes or os.cpu_count()
        self.download_results = []
        self._executor = concurrent.futures.ThreadPoolExecutor(max_workers=self.num_processes)

    def download_files(self, urls: List[str], filenames: List[str]) -> None:
        for url, filename in zip(urls, filenames):
            future = self._executor.submit(self._download_file, url, filename)
            self.download_results.append(future)

    def _download_file(self, url: str, filename: str) -> bool:
        try:
            response = requests.get(url)
            if response.status_code == 200:
                with open(filename, 'wb') as file:
                    file.write(response.content)
                return True
            else:
                print(f""Failed to download {url}. Response code: {response.status_code}"")
                return False
        except Exception as e:
            print(f""Error occurred while downloading {url}: {e}"")
            return False

    def wait_for_completion(self) -> None:
        for future in concurrent.futures.as_completed(self.download_results):
            result = future.result()
            if not result:
                print(""One or more downloads failed. Please check logs."")

def main():
    urls = ['http://example.com/largefile1', 'http://example.com/largefile2']
    filenames = ['largefile1.bin', 'largefile2.bin']

    manager = FileDownloaderManager()
    manager.download_files(urls, filenames)

    manager.wait_for_completion()

if __name__ == '__main__':
    main()
