This comprehensive exercise showcases proficiency in object-oriented programming principles such as encapsulation, inheritance, and polymorphism while also emphasizing error handling, dynamic data generation, and efficient memory management in Python.",330,,"['```python
import random

class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        if not isinstance(value, int):
            raise ValueError(""Value must be an integer."")
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert_recursive(self.root, value)

    def _insert_recursive(self, node, value):
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._insert_recursive(node.left, value)
        elif value > node.value:
            if node.right is None:
                node.right = Node(value)
            else:
                self._insert_recursive(node.right, value)
        else:
            raise ValueError(""Duplicate values are not allowed."")

    def in_order_traversal(self):
        result = []
        self._in_order_recursive(self.root, result)
        return result

    def _in_order_recursive(self, node, result):
        if node is not None:
            self._in_order_recursive(node.left, result)
            result.append(node.value)
            self._in_order_recursive(node.right, result)

    def pre_order_traversal(self):
        result = []
        self._pre_order_recursive(self.root, result)
        return result

    def _pre_order_recursive(self, node, result):
        if node is not None:
            result.append(node.value)
            self._pre_order_recursive(node.left, result)
            self._pre_order_recursive(node.right, result)

    def post_order_traversal(self):
        result = []
        self._post_order_recursive(self.root, result)
        return result

    def _post_order_recursive(self, node, result):
        if node is not None:
            self._post_order_recursive(node.left, result)
            self._post_order_recursive(node.right, result)
            result.append(node.value)

    def find_min(self):
        if self.root is None:
            raise ValueError(""Tree is empty."")
        return self._find_min_recursive(self.root)

    def _find_min_recursive(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current.value

    def find_max(self):
        if self.root is None:
            raise ValueError(""Tree is empty."")
        return self._find_max_recursive(self.root)

    def _find_max_recursive(self, node):
        current = node
        while current.right is not None:
            current = current.right
        return current.value

    def delete_node(self, value):
        if not isinstance(value, int):
            raise ValueError(""Value must be an integer."")
        self.root = self._delete_recursive(self.root, value)

    def _delete_recursive(self, node, value):
        if node is None:
            return node
        if value < node.value:
            node.left = self._delete_recursive(node.left, value)
        elif value > node.value:
            node.right = self._delete_recursive(node.right, value)
        else:
            if node.left is None:
                temp = node.right
                node = None
                return temp
            elif node.right is None:
                temp = node.left
                node = None
                return temp
            temp = self._find_min_recursive(node.right)
            node.value = temp.value
            node.right = self._delete_recursive(node.right, temp.value)
        return node

# Example usage:
if __name__ == ""__main__"":
    tree = BinaryTree()
    for _ in range(10):
        value = random.randint(1, 100)
        tree.insert(value)

    print(""In-order traversal:"", tree.in_order_traversal())
    print(""Pre-order traversal:"", tree.pre_order_traversal())
    print(""Post-order traversal:"", tree.post_order_traversal())
    print(""Minimum value:"", tree.find_min())
    print(""Maximum value:"", tree.find_max())

    # Delete a node
    tree.delete_node(50)
    print(""In-order traversal after deletion:"", tree.in_order_traversal())
```']",252,[0],[],True,0,0,0,

