0,"Create a Python script that accepts a URL as input, employs the requests library to fetch the URL's HTTP response, and extracts the server's IP address from the 'X-Forwarded-For' header. Handle potential exceptions and return an error code if the operation fails or if the header is not present. Ensure to account for constraints related to process execution capabilities.",590,,"['```python
import requests

def get_server_ip(url):
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()

        x_forwarded_for = response.headers.get('X-Forwarded-For')
        if x_forwarded_for is not None:
            return x_forwarded_for.split(',')[0].strip()
        else:
            return ""Error: X-Forwarded-For header not present""
    except requests.RequestException as e:
        return f""Error: {str(e)}""
    except Exception as e:
        return f""Error: Unexpected error - {str(e)}""

# Example usage
url = input(""Enter a URL to fetch the server IP from: "")
print(get_server_ip(url))
